# Terraform Module: S3 + RDS + IAM

Below is a production-ready Terraform module structure supporting dev/prod environments via `tfvars` files.

## Directory Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

## Root Module: `versions.tf`

```hcl
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Uncomment to use S3 backend per environment
  # backend "s3" {
  #   encrypt        = true
  #   dynamodb_table = "terraform-locks"
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
      CreatedAt   = var.created_at
    }
  }
}
```

---

## Root Module: `variables.tf`

```hcl
variable "environment" {
  type        = string
  description = "Environment name (dev or prod)"
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}

variable "created_at" {
  type        = string
  description = "Creation timestamp for tagging"
  default     = ""
}

# S3 Variables
variable "s3_bucket_name" {
  type        = string
  description = "S3 bucket name (must be globally unique)"
}

variable "s3_replication_region" {
  type        = string
  description = "Region for S3 cross-region replication (prod only)"
  default     = "us-west-2"
}

variable "enable_s3_replication" {
  type        = bool
  description = "Enable cross-region replication for S3 (prod only)"
  default     = false
}

# RDS Variables
variable "rds_instance_class" {
  type        = string
  description = "RDS instance class (e.g., db.t3.micro, db.t3.medium)"
  default     = "db.t3.micro"
}

variable "rds_allocated_storage" {
  type        = number
  description = "Allocated storage in GB"
  default     = 20
}

variable "rds_db_name" {
  type        = string
  description = "Initial database name"
  default     = "appdb"
}

variable "rds_username" {
  type        = string
  description = "Master username"
  default     = "postgres"
  sensitive   = true
}

variable "rds_password" {
  type        = string
  description = "Master password (use AWS Secrets Manager in production)"
  sensitive   = true
}

variable "rds_multi_az" {
  type        = bool
  description = "Enable Multi-AZ deployment"
  default     = false
}

variable "rds_backup_retention_days" {
  type        = number
  description = "Backup retention period in days"
  default     = 7
}

# IAM Variables
variable "service_account_name" {
  type        = string
  description = "Service account name/prefix"
}

variable "oidc_provider_arn" {
  type        = string
  description = "OIDC provider ARN for role assumption (prod only)"
  default     = ""
}

variable "oidc_subject" {
  type        = string
  description = "OIDC subject for role trust policy"
  default     = ""
}
```

---

## Root Module: `main.tf`

```hcl
module "s3" {
  source = "./modules/s3"

  bucket_name              = var.s3_bucket_name
  environment              = var.environment
  enable_replication       = var.enable_s3_replication
  replication_region       = var.s3_replication_region
  replication_bucket_name  = var.enable_s3_replication ? "${var.s3_bucket_name}-${var.s3_replication_region}" : ""
}

module "rds" {
  source = "./modules/rds"

  identifier           = "${var.service_account_name}-db-${var.environment}"
  instance_class       = var.rds_instance_class
  allocated_storage    = var.rds_allocated_storage
  db_name              = var.rds_db_name
  username             = var.rds_username
  password             = var.rds_password
  multi_az             = var.rds_multi_az
  backup_retention_days = var.rds_backup_retention_days
  environment          = var.environment
}

module "iam" {
  source = "./modules/iam"

  service_account_name = var.service_account_name
  environment          = var.environment
  s3_bucket_arn        = module.s3.bucket_arn
  rds_resource_id      = module.rds.resource_id
  rds_arn              = module.rds.arn
  oidc_provider_arn    = var.oidc_provider_arn
  oidc_subject         = var.oidc_subject
}
```

---

## Root Module: `outputs.tf`

```hcl
output "s3_bucket_name" {
  value       = module.s3.bucket_name
  description = "S3 bucket name"
}

output "s3_bucket_arn" {
  value       = module.s3.bucket_arn
  description = "S3 bucket ARN"
}

output "rds_endpoint" {
  value       = module.rds.endpoint
  description = "RDS instance endpoint"
  sensitive   = true
}

output "rds_resource_id" {
  value       = module.rds.resource_id
  description = "RDS resource ID for tagging and cross-stack references"
}

output "iam_role_arn" {
  value       = module.iam.role_arn
  description = "IAM role ARN for service account"
}

output "iam_access_key_id" {
  value       = module.iam.access_key_id
  description = "IAM user access key ID (store securely)"
  sensitive   = true
}

output "db_connection_string" {
  value       = "postgresql://${var.rds_username}@${module.rds.endpoint}/${var.rds_db_name}"
  description = "PostgreSQL connection string (HANDLE SECURELY)"
  sensitive   = true
}
```

---

## Module: `modules/s3/variables.tf`

```hcl
variable "bucket_name" {
  type        = string
  description = "S3 bucket name"
}

variable "environment" {
  type        = string
  description = "Environment name"
}

variable "enable_replication" {
  type        = bool
  description = "Enable cross-region replication"
  default     = false
}

variable "replication_region" {
  type        = string
  description = "Target region for replication"
  default     = "us-west-2"
}

variable "replication_bucket_name" {
  type        = string
  description = "Replication bucket name"
  default     = ""
}
```

---

## Module: `modules/s3/main.tf`

```hcl
# Primary S3 bucket
resource "aws_s3_bucket" "primary" {
  bucket = var.bucket_name
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication bucket (prod only)
resource "aws_s3_bucket" "replica" {
  count  = var.enable_replication ? 1 : 0
  bucket = var.replication_bucket_name

  provider = aws.replica
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  provider = aws.replica

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  provider = aws.replica

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication IAM role
resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.primary.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.primary.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count       = var.enable_replication ? 1 : 0
  role        = aws_iam_role.replication[0].name
  policy_arn  = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.primary]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket       = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}
```

