## Module: `modules/iam/main.tf`

```hcl
# IAM User (dev only, for programmatic access)
resource "aws_iam_user" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  name  = "${var.service_account_name}-user-${var.environment}"

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_access_key" "service_account" {
  count = var.environment == "dev" ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}

# IAM Role for OIDC trust (prod only)
resource "aws_iam_role" "service_account" {
  count = var.environment == "prod" && var.oidc_provider_arn != "" ? 1 : 0
  name  = "${var.service_account_name}-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub" = var.oidc_subject
          }
        }
      }
    ]
  })
}

# Fall back to standard role in dev or if OIDC not configured
resource "aws_iam_role" "service_account_fallback" {
  count = var.environment == "dev" || var.oidc_provider_arn == "" ? 1 : 0
  name  = "${var.service_account_name}-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# S3 Policy (least privilege)
resource "aws_iam_policy" "s3_access" {
  name        = "${var.service_account_name}-s3-policy-${var.environment}"
  description = "S3 access policy for ${var.service_account_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketVersioning"
        ]
        Resource = var.s3_bucket_arn
      },
      {
        Sid    = "ReadWriteObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${var.s3_bucket_arn}/*"
      }
    ]
  })
}

# RDS Policy (least privilege, no wildcards in prod)
resource "aws_iam_policy" "rds_access" {
  name        = "${var.service_account_name}-rds-policy-${var.environment}"
  description = "RDS access policy for ${var.service_account_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeDB"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBParameterGroups"
        ]
        Resource = var.environment == "prod" ? var.rds_arn : "*"
      }
    ]
  })
}

# Attach policies to user (dev) or role (prod)
resource "aws_iam_user_policy_attachment" "s3" {
  count      = var.environment == "dev" ? 1 : 0
  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_iam_user_policy_attachment" "rds" {
  count      = var.environment == "dev" ? 1 : 0
  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_policy.rds_access.arn
}

resource "aws_iam_role_policy_attachment" "s3" {
  count      = var.environment == "prod" || var.oidc_provider_arn != "" ? 1 : 0
  role       = try(aws_iam_role.service_account[0].name, aws_iam_role.service_account_fallback[0].name)
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_iam_role_policy_attachment" "rds" {
  count      = var.environment == "prod" || var.oidc_provider_arn != "" ? 1 : 0
  role       = try(aws_iam_role.service_account[0].name, aws_iam_role.service_account_fallback[0].name)
  policy_arn = aws_iam_policy.rds_access.arn
}
```

